    "support_text": "A análise do sangue é normalmente o primeiro passo na avaliação da função hematológica e no diagnóstico de doenças relacionadas, uma vez que muitos distúrbios hematológicos são definidos por exames de sangue específicos.\nNesse contexto, analise as afirmativas a seguir.\nI. A análise de esfregaços de sangue e de parâmetros hematológicos fornece informações diagnósticas importantes acerca da morfologia celular e da quantificação dos componentes celulares do sangue, além da avaliação do tamanho e da forma da célula.\nII. Os elementos sanguíneos incluem eritrócitos ou glóbulos vermelhos, leucócitos ou glóbulos brancos e plaquetas.\nIII. Os leucócitos são as células sanguíneas presentes em maior quantidade no sangue e são necessárias para a respiração dos tecidos.",
