    "type": "multiple_choice",
    "support_text": "No que diz respeito ao processamento e preservação de amostras hematológicas, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa.\n( ) O sangue, normalmente, é coletado por punção venosa em tubos específicos para coleta contendo anticoagulante. A heparina e o citrato dissódico atuam na remoção do cálcio do sangue, que é necessário para o início do processo de coagulação. O ácido etilenodiaminotetracético (EDTA) age formando um complexo com a antitrombina no plasma para prevenir a formação de trombina.\n( ) Fatores como o nível de hidratação, o uso medicamentoso, tabagismo e a ansiedade podem afetar os parâmetros hematológicos, de modo que as amostras devem ser coletadas de maneira padronizada para reduzir a variabilidade dos dados.\n( ) A idade da amostra pode afetar a qualidade dos dados coletados. Desta forma, dados como idade, sexo e horário da coleta da amostra do paciente devem ser anotados, bem como as informações clínicas pertinentes correlacionadas.",
