    "support_text": "Charge sob a legenda 'NAS ESTRADAS...': Um motorista ao volante de seu carro com os faróis apagados vê o policial rodoviário e pergunta: 'O QUE É ISSO?'. O policial rodoviário aponta para os faróis do carro e responde: 'ACENDA O FAROL QUE VAI VER QUE É UMA MULTA!'",
