    "statement": "Paula está parada, de pé, em frente a um poste vertical, sobre uma rua horizontal. Para olhar diretamente para o topo do poste, Paula precisa erguer sua linha de visão em 45° com relação à horizontal. A distância de Paula até o poste é igual",
