    "explanation": {
      "summary": "Gabarito: C (Diferença entre altura do poste e altura dos olhos).",
      "details": "Forma-se um triângulo retângulo onde o cateto vertical é a diferença entre a altura do poste (H) e a altura dos olhos de Paula (h): Cateto vertical = H - h. Como o ângulo de visão é de 45°, temos tg(45°) = 1 = (H - h) / d => d = H - h. Portanto, a distância é igual à diferença entre a altura do poste e a altura dos olhos de Paula."
    }
