    "statement": "Wilma abastece o seu carro colocando 36 litros de um combustível no qual 20% é álcool e 80%, gasolina. Entretanto, no momento do abastecimento, já havia, no tanque do carro, 12 litros de outro combustível em que 25% era álcool e o restante, gasolina. Após o abastecimento, a quantidade de álcool na mistura dos dois combustíveis no tanque do carro passou a ser de",
