    "support_text": "Sejam V1, V2, V3, ..., V9, V10 os dez vértices de um decágono regular convexo, nomeados no sentido horário. Sejam D1, D2 e D3, respectivamente, as distâncias de V1 a V4, de V2 a V6 e de V5 a V9.",
