    "support_text": "Danilo deseja pintar 4 paredes e o teto de sua sala em forma de paralelepípedo (5m de comp., 4m de larg., 2,5m de altura). Não há janelas e possui apenas uma porta de 2m x 0,75m. O chão não será pintado e dará 3 demãos. Cada galão de tinta custa R$ 72,00 e pinta até 54 m².",
