      "details": "• Área do teto = 5 * 4 = 20 m².\n• Área das 4 paredes = 2 * (5 * 2,5) + 2 * (4 * 2,5) = 25 + 20 = 45 m².\n• Área da porta = 2 * 0,75 = 1,5 m².\n• Área líquida para 1 demão = 20 + 45 - 1,5 = 63,5 m².\n• Para 3 demãos = 63,5 * 3 = 190,5 m².\n• Cada galão rende 54 m²: 190,5 / 54 ≈ 3,52 galões => são necessários 4 galões inteiros.\n• Gasto total = 4 * R$ 72,00 = R$ 288,00."
