      "details": "Uma condicional 'P → Q' é falsa se, e somente se, o antecedente P for VERDADEIRO e o consequente Q for FALSO.\n• Antecedente (a ∧ b) = V => tanto 'a' quanto 'b' são verdadeiras.\n• Consequente (c ∨ d) = F => tanto 'c' quanto 'd' são falsas.\nLogo, a e b têm valor verdadeiro e c e d têm valor falso."
