      "details": "Se a probabilidade de ser branca é 2/9, a probabilidade de ser preta é 1 - 2/9 = 7/9.\nIsso significa que a quantidade de bolas pretas deve ser um número inteiro múltiplo de 7 (P = 7k, onde k é um inteiro positivo).\nDentre as alternativas (14, 15, 16, 17, 18), o único múltiplo de 7 é 14 (quando k = 2, com 4 brancas e 14 pretas, totalizando 18 bolas)."
