    "support_text": "Jair comprou 45 balas e distribuiu entre 3 filhos de forma inversamente proporcional às suas idades. O mais novo tem 6 anos e recebeu 20 balas. O mais velho tem 12 anos. O total distribuído foi 45 balas.",
