    "explanation": {
      "summary": "Gabarito: B (8 anos).",
      "details": "Na divisão inversamente proporcional, a quantidade de balas vezes a idade é uma constante K.\n• Para o mais novo (6 anos, 20 balas): K = 6 * 20 = 120.\n• Para o mais velho (12 anos): Balas = K / 12 = 120 / 12 = 10 balas.\n• O total é 45 balas, logo o filho do meio recebeu: 45 - 20 - 10 = 15 balas.\n• Idade do filho do meio: Idade = K / 15 = 120 / 15 = 8 anos."
    }
