    "support_text": "Os requisitos de Boas Práticas de Funcionamento para os Serviços de Saúde estabelecem disposições sobre a Proteção à Saúde do Trabalhador:\n( ) O Serviço de Saúde deve garantir que os trabalhadores com agravos agudos à saúde ou com lesões nos membros superiores só iniciem suas atividades após a avaliação médica.\n( ) É responsabilidade do Serviço de Saúde garantir mecanismos de prevenção dos riscos de acidentes de trabalho, incluindo o fornecimento de Equipamentos de Proteção Individual – EPI.\n( ) Os trabalhadores com possibilidade de exposição a agentes biológicos, físicos ou químicos precisam usar vestimentas para o trabalho que devem ser obrigatoriamente fornecidas pelo Serviço de Saúde, não sendo recomendado o uso de vestimentas do próprio trabalhador.",
