    "support_text": "A coloração de Gram diferencia bactérias gram-positivas (púrpura) e gram-negativas (rosa).\nI. Como as bactérias gram-positivas apresentam uma membrana externa contendo lipídeos e peptideoglicano delgado, elas perdem a corante púrpura quando tratadas com álcool-acetona.\nII. As bactérias gram-positivas têm a capacidade de reter o complexo cristal violeta-iodo na presença de um solvente de lipídeos, geralmente álcool-acetona.\nIII. As bactérias gram-negativas retêm o complexo cristal violeta-iodo na presença de um solvente de lipídeos, geralmente álcool-acetona.",
