    "support_text": "Com relação aos meios de cultura utilizados em microbiologia:\n( ) Um meio sintético definido contém quantidades específicas e conhecidas de substâncias químicas.\n( ) Meios complexos possuem composição química exata e constante entre diferentes lotes.\n( ) A peptona é um ingrediente comum em meios complexos e fornece pequenos peptídeos utilizáveis por microrganismos.\n( ) Meios contendo sangue podem ser úteis para cultivar microrganismos fastidiosos e para identificar hemólise.\n( ) Organismos como os que causam sífilis e hanseníase podem ser facilmente cultivados em meios sintéticos definidos.",
