    "support_text": "Acerca da importância e propriedades da água para os seres vivos:\n( ) A água tem várias propriedades que a tornam importante para os seres vivos.\n( ) Por ser um composto polar e apresentar pontes de hidrogênio, a água pode formar finas camadas nas superfícies e pode atuar como solvente ou meio de dissolução.\n( ) A água é um bom solvente para íons, visto que suas moléculas polares circundam os íons.\n( ) A região positiva das moléculas de água é atraída pelos íons negativos, enquanto a região negativa das moléculas de água é atraída por íons positivos.\n( ) A água não é um bom solvente para íons, visto que suas moléculas apolares circundam os íons.",
