    "support_text": "Com relação às micoses observadas no Brasil:\nI. As dermatofitoses, dermatomicoses dicrômicas, tricomicoses nodulares e candidíases superficiais são micoses superficiais.\nII. Esporotricoses, paracoccidioidomicose, criptococose e rinosporidiose são micoses profundas.\nIII. Diabetes, subnutrição, câncer, leucemia, aids e outras afecções degenerativas facilitam a sobrevivência de fungos no organismo.",
