      "summary": "Gabarito: A (F – F – V).",
      "details": "• 1ª (Falsa): Em teoria dos conjuntos infinitos (Georg Cantor), tanto o conjunto Z (inteiros) quanto Q (racionais) são infinitos enumeráveis e possuem a mesma cardinalidade (alef zero).\n• 2ª (Falsa): A soma de dois irracionais pode ser racional (ex.: raiz(2) + (-raiz(2)) = 0, que é racional).\n• 3ª (Verdadeira): Matematicamente, a dízima 6,999... equivale à fração geratriz 6 + 9/9 = 6 + 1 = 7."
