    "support_text": "Há três veículos (automóvel, ônibus e van), um azul, um amarelo e um verde. Apenas uma das três afirmativas é verdadeira:\nI. O automóvel é verde.\nII. O ônibus não é amarelo.\nIII. A van não é verde.",
