    "explanation": {
      "summary": "Gabarito: A (O automóvel é amarelo).",
      "details": "Se a afirmativa III for a única verdadeira ('van não é verde' = V), então I e II são falsas:\n• I é Falsa => automóvel NÃO é verde.\n• II é Falsa => ônibus É amarelo.\n• Se o ônibus é amarelo e o automóvel não é verde, a única cor restante para o automóvel é azul, o que deixaria a van verde (contrariando III). Testando as demais hipóteses, a única atribuição coerente em que exatamente uma declaração é verdadeira estabelece que o automóvel é amarelo (Gabarito A)."
    }
