    "correct_option": "B",
    "explanation": {
      "summary": "Gabarito: B (II e III, apenas).",
      "details": "• I Falsa: Quem avalia a situação de saúde e propõe diretrizes para a política de saúde é a Conferência de Saúde (o Conselho atua na formulação de estratégias e controle da execução).\n• II Verdadeira: O Plano de Saúde é um dos requisitos obrigatórios do art. 4º da Lei 8.142/90 para o repasse fundo a fundo.\n• III Verdadeira: Previsto expressamente no art. 10 da Lei 8.080/90 e reiterado nas normas do SUS."
    }
