    "support_text": "Para evitar a exposição ocupacional a radiações ionizantes, os trabalhadores devem adotar os princípios básicos de proteção radiológica:\nI. aumentar a distância e diminuir o tempo de exposição à fonte de radiação ionizante.\nII. usar as barreiras, neste caso o uso dos equipamentos de proteção individual (EPI).\nIII. usar equipamento de proteção coletiva (EPC) ou vestimentas de proteção coletivas.",
