      "details": "Os três pilares clássicos da proteção radiológica operacional são: 1) Tempo (menor possível); 2) Distância (maior possível em relação à fonte, pela lei do inverso do quadrado da distância); e 3) Blindagem (barreiras físicas, biombos plumbíferos - EPC e aventais de chumbo/protetores de tireoide - EPI)."
