    "topic": "Infraestrutura, Rodovia BR-153 (Belém-Brasília) e Territorialização",
    "type": "multiple_choice",
    "support_text": "Foram inegáveis os desdobramentos socioeconômicos sobre o antigo Norte Goiano fruto da construção da rodovia BR-153, a partir do final da década de 1950. O novo urbanismo da Belém-Brasília trouxe enorme impacto no que se refere ao conjunto de cidades que existiam às margens do rio Tocantins, aos fluxos migratórios e às atividades econômicas da região.\n(Adaptado de AQUINO, N. Tocantins: cidades e urbanismo em três modelos históricos. In: III Encontro da ANPPAS. Brasília, 2006, p. 8.)",
    "statement": "As afirmativas a seguir descrevem corretamente impactos da rodovia BR-153 no processo de territorialização do Tocantins, à exceção de uma. Assinale-a.",
    "options": [
      {
        "id": "A",
        "text": "A rodovia foi construída no governo Kubitschek, em um contexto desenvolvimentista que considerava a expansão rodoviária como um meio para integrar econômica e territorialmente as regiões do país, inclusive o norte goiano que, então, vivia uma situação de abandono."
      },
      {
        "id": "B",
        "text": "A rodovia Belém-Brasília teve grande importância para a urbanização do atual Tocantins, o que é exemplificado pela quantidade de novas cidades criadas após a sua construção, como Araguaína, Gurupi, Paraíso do Tocantins, Colinas do Tocantins e Guaraí."
      },
      {
        "id": "C",
        "text": "A construção da BR-153 alavancou também os municípios ribeirinhos, pois a navegação fluvial foi intensificada para abastecer as obras em curso, o que transformou esses municípios em satélites econômicos da nova malha urbana instalada ao longo da rodovia."
      },
      {
        "id": "D",
        "text": "Após a abertura da rodovia, as principais áreas que receberam fluxos migratórios foram a Microrregião de Gurupi – Gurupi e a Microrregião de Porto Nacional – Palmas, para onde se dirigiram pessoas interessadas em trabalhar na construção civil, nos serviços e no comércio, entre outros."
      },
      {
        "id": "E",
        "text": "A BR-153 permitiu interligar o norte de Goiás, atual Estado do Tocantins, a outras localidades do país, facilitando o escoamento da produção e o acesso a produtos para a região, promovendo o fluxo de mercadorias e serviços."
      }
    ],
    "correct_option": "C",
    "explanation": {
      "summary": "Gabarito: C (Incorreta). A BR-153 não alavancou os portos e cidades ribeirinhas do rio Tocantins; ao contrário, causou seu declínio ao transferir o eixo econômico para o modal rodoviário.",
      "details": "A rodovia Belém-Brasília (BR-153) deslocou o eixo de ocupação e comércio do antigo norte goiano. Os povoados e cidades ribeirinhas do rio Tocantins que antes dependiam do vapor e da navegação fluvial sofreram forte esvaziamento e isolamento econômico, enquanto as cidades fundadas ou expandidas ao longo da faixa de asfalto da rodovia assumiram o protagonismo comercial e populacional."
    }
