    "type": "multiple_choice",
    "support_text": "O Memorial Coluna Prestes (2001) é uma obra do arquiteto Oscar Niemeyer localizada na Praça dos Girassóis, no centro de Palmas (TO).\n\nA respeito da relação entre essa obra e a constituição de uma memória histórica para o Estado do Tocantins, analise as afirmativas a seguir:\nI. O monumento refere-se à Coluna Prestes, que percorreu o Brasil para divulgar seu programa revolucionário entre 1924 e 1927, tendo passado pelo Norte do então Estado de Goiás (atual Tocantins) durante seu percurso.\nII. A obra foi realizada em concreto e apresenta curvas sinuosas, características próprias do Barroco das cidades mineradoras, estabelecendo visualmente uma continuidade entre o Barroco do passado das cidades mineradoras e o presente do Tocantins.\nIII. A construção do memorial permite inserir simbolicamente a história do Tocantins nos grandes processos da história republicana nacional, e homenagear o Tenente Antônio de Siqueira Campos, cujo sobrenome é homônimo ao do ex-governador do Estado.",
