      "details": "I. Correta: A marcha da Coluna Prestes percorreu centenas de quilômetros no norte goiano (atual Tocantins) entre 1925 e 1926. II. Incorreta: O traço curvo de Oscar Niemeyer pertence à Arquitetura Moderna Brasileira (concreto armado e linhas plásticas), e não ao estilo Barroco colonial. III. Correta: O monumento valoriza os tenentistas e presta homenagem particular ao tenente Antônio de Siqueira Campos, criando elo simbólico com a figura do governador José Wilson Siqueira Campos."
