      "details": "1º item (Falso): O Tocantins possui relevo plano e clima tropical de estação chuvosa muito favoráveis à agricultura de oleaginosas no Cerrado. 2º item (Verdadeiro): O estado conta com usinas de biodiesel (como em Porto Nacional) autorizadas pela ANP, aptas a processar soja e matérias-primas vegetais. 3º item (Verdadeiro): Pela alta taxa de irradiação solar e incentivo estadual com isenções do programa Pró-Solar (Lei Estadual 3.006/2015), o Tocantins expande fortemente parques solares fotovoltaicos."
