    "support_text": "As belas paisagens como serras, cachoeiras, praias e até mesmo dunas, fazem do Tocantins um paraíso de paisagens naturais, atraindo turistas de várias regiões para conhecer o mais novo Estado brasileiro. A potencialidade para o ecoturismo e a preocupação em conservar a biodiversidade e recursos naturais nele contidos fez com que o Governo do Estado, criasse e implementasse as Unidades de Conservação Ambiental (UC).\n(Adaptado de https://www.to.gov.br/secom/)",
