    "type": "multiple_choice",
    "support_text": "O Estado do Tocantins possui diversas comunidades quilombolas certificadas e outras com processo formalizado para regularização fundiária de seus territórios. A definição de comunidade quilombola é dada pelo Art. 2º do Decreto nº 4.887/2003:\n'Consideram-se remanescentes das comunidades dos quilombos, para os fins deste Decreto, os grupos étnico-raciais, segundo critérios de auto-atribuição, com trajetória histórica própria, dotados de relações territoriais específicas, com presunção de ancestralidade negra relacionada com a resistência à opressão histórica sofrida.'",
    "statement": "A respeito dos órgãos e processos envolvidos na identificação e regularização de territórios quilombolas no Estado do Tocantins, assinale a afirmativa correta.",
