      {
        "id": "D",
        "text": "A certificação quilombola é realizada pela Fundação Cultural Palmares, que avalia com visitas técnicas a autenticidade do legado quilombola pretendido e, caso o aprove, emite a certidão de comunidade quilombola e a inscreve em um cadastro geral."
      },
      {
        "id": "E",
        "text": "O acesso às terras ocupadas pelos remanescentes das comunidades dos quilombos é garantido por sua delimitação e titulação, a cargo da autoridade municipal em que a mesma se localiza."
      }
