      "details": "A certidão expedida pela Fundação Cultural Palmares (órgão do Governo Federal) formaliza o autorreconhecimento da comunidade quilombola, viabilizando o ingresso em programas de assistência, educação quilombola, saúde da família e abrindo a fase de regularização fundiária. Erros das demais: não se exige prova genética ou religiosidade específica; a titulação das terras compete ao INCRA/órgão fundiário estadual (Itertins), não à prefeitura/autoridade municipal."
